import { test } from "node:test";
import assert from "node:assert";
import { sweep } from "../src/inventory/reaper.ts";

test("the reaper keeps holds that have not expired", () => {
  const now = new Date(1700000000000);
  const live = { sku: "a", qty: 1, expiresAt: new Date(now.getTime() + 60_000) };
  const dead = { sku: "b", qty: 2, expiresAt: new Date(now.getTime() - 60_000) };
  assert.deepEqual(sweep([live, dead], now), [live]);
});
BENCHEOF
